# Install a small helper adjacent to type-knowledge hashing if absent.
fingerprint = ROOT / "phalcom-semantic/src/db/fingerprint.rs"
ftext = fingerprint.read_text()
if "fn hash_type_knowledge_option(" not in ftext:
    anchor = "fn hash_dispatch_callable_signature("
    pos = ftext.index(anchor)
    helper = '''fn hash_type_knowledge_option(value: &Option<TypeKnowledge>, include_provenance: bool, hasher: &mut impl Hasher) {\n    match value {\n        Some(knowledge) => {\n            1u8.hash(hasher);\n            hash_type_knowledge(knowledge, include_provenance, hasher);\n        }\n        None => 0u8.hash(hasher),\n    }\n}\n\n'''
    fingerprint.write_text(ftext[:pos] + helper + ftext[pos:])

